CREATE EXTENSION IF NOT EXISTS pgcrypto;

ALTER TABLE patients ADD COLUMN ssn_enc bytea;

-- Encrypt on write (key supplied by the application, not hard-coded)
UPDATE patients
SET ssn_enc = pgp_sym_encrypt(ssn, current_setting('app.enc_key'))
WHERE ssn IS NOT NULL;

-- Decrypt on read for authorised users only
SELECT
    id,
    pgp_sym_decrypt(ssn_enc, current_setting('app.enc_key')) AS ssn
FROM patients
WHERE id = 42;
